dataset_catalog.text:
{
  "name": "get_congress_trades",
  "description": "Get stock transactions by members of the U.S. Congress. Filter by ticker symbol, politician name, chamber (Senate or House), party, date range, and more. Returns trade details including transaction type, amount range, and filing date.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_congress_politician",
  "description": "Get detailed information about a U.S. Congress member including their profile, net worth, stock portfolio, top donors, and recent trading activity. Use bioguide_id or politician name to look up a specific member.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_congress_legislation",
  "description": "Get bills, legislation, and AI-generated bill summaries from Congress. Includes sponsorship information and current status.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_insider_trading",
  "description": "Get SEC Form 4 insider trading transactions. Shows when company executives, directors, and major shareholders buy or sell stock. Filter by ticker or date.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_institutional_holdings",
  "description": "Get SEC 13F institutional holdings data. Shows what stocks hedge funds and institutional investors hold, and how their positions changed. Filter by ticker, fund owner, date, or reporting period.",
  "tier": 2,
  "tier_label": "Trader+"
}
{
  "name": "get_gov_contracts",
  "description": "Get government contracts and awards by ticker symbol. Shows which companies receive federal contracts and for how much.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_lobbying",
  "description": "Get corporate lobbying spending data. Shows how much companies spend on lobbying Congress, and which issues they lobby on.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_ticker_ownership",
  "description": "Get ownership data for a stock: insider holdings, institutional holders (13F), ownership breakdown, and executive compensation.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_dark_pool",
  "description": "Get off-exchange (dark pool) trading data for a stock. Shows the volume of trades happening outside public exchanges.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_patents",
  "description": "Get patent filing data for a company including patent count, filing trends (drift), and momentum metrics.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_political_exposure",
  "description": "Get a comprehensive political exposure report for a stock ticker. Combines Congress trading activity, lobbying spending, government contracts, and political beta into a single analysis.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_ticker_full_picture",
  "description": "Get a combined picture of a stock: ownership breakdown (insider sentiment, 13F summary, top owners) and recent insider trading in one response.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "compare_tickers",
  "description": "Compare 2-3 stock tickers side by side across any available dataset (congress trades, insider trading, ownership, social sentiment, etc.).",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "search_datasets",
  "description": "Discover what data is available in QuiverQuant. Returns a list of all available tools with their descriptions, required parameters, and which subscription tier is needed. Use this first if you're unsure which tool to call.",
  "tier": 0,
  "tier_label": "Free"
}
{
  "name": "query_quiver_api",
  "description": "Direct access to any QuiverQuant API endpoint by name. Pass the endpoint name (e.g. 'live_congress_trading') and parameters as key-value pairs. Use search_datasets first to discover available endpoints.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_corporate_donors",
  "description": "Get corporate PAC donation history from FEC filings. Filter by ticker (the donating company), politician (candidate name), bioguide_id, party, cycle, and date range. All results restricted to PAC transactions.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_executive_compensation",
  "description": "Get SEC executive compensation disclosures from proxy filings. Filter by ticker, executive name, role, year range, and minimum total compensation. Year-over-year change fields are not computed by this tool.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_quiver_newsfeed",
  "description": "Get curated news from the Quiver newsfeed. Filter by ticker, category, source, text query (headline ilike), date range, or breaking-only. Subreddit cross-posts and earnings-call-summary boilerplate are excluded from results.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
{
  "name": "get_trump_trades",
  "description": "Get stock transactions by U.S. President Donald Trump (STOCK Act disclosures). Filter by ticker, company name, transaction type (Purchase/Sale/Exchange), and date range. Date filter applies to either the disclosure date (filed) or transaction date (traded) via the date_field parameter.",
  "tier": 1,
  "tier_label": "Hobbyist+"
}
